'use client'
import { createContext, useRef, useState, type Dispatch, type ReactNode, type SetStateAction } from 'react'

// Menu triggers in a row on the paper (shadcn's menubar in Conare's grammar): a hairline strip, 28px triggers in 12px
// medium, each opening Menu's square panel of rows (MenubarMenu). One trigger is in the tab order; Left and Right move
// along the row, Down, Enter or Space open, and with a menu open Left and Right open the next one. While one is open,
// pointing at another trigger switches to it at once.
export interface MenubarEntry { key: string, el: () => HTMLElement | null, open: () => Promise<void> }
export interface MenubarContextValue {
  active: string | null
  setActive: Dispatch<SetStateAction<string | null>>
  focused: string | null
  setFocused: Dispatch<SetStateAction<string | null>>
  entries: MenubarEntry[]
  move: (from: string, step: number, open: boolean) => void
}
export const MenubarContext = createContext<MenubarContextValue | null>(null)
export interface MenubarProps { label: string, children?: ReactNode }

export function Menubar({ label, children }: MenubarProps) {
  const [active, setActive] = useState<string | null>(null)
  const [focused, setFocused] = useState<string | null>(null)
  const entries = useRef<MenubarEntry[]>([]).current
  function move(from: string, step: number, open: boolean) {
    const at = entries.findIndex(e => e.key === from)
    const next = entries[(at + step + entries.length) % entries.length]
    if (!next) return
    setFocused(next.key)
    next.el()?.focus()
    if (open) void next.open()
  }
  return (
    <MenubarContext.Provider value={{ active, setActive, focused, setFocused, entries, move }}>
      <div data-ds="menubar" role="menubar" aria-label={label} className="inline-flex items-center gap-0.5 border border-edge bg-surface-subtle p-0.5">
        {children}
      </div>
    </MenubarContext.Provider>
  )
}

export default Menubar

'use client'
import { useContext, useEffect, useId, useRef, type KeyboardEvent, type MouseEvent, type ReactNode } from 'react'
import { MenuClose } from '@/react/components/ui/Menu'
import { MenubarContext } from '@/react/components/ui/Menubar'
import { PopoverPanel } from '@/react/components/ui/PopoverPanel'
import { onMenuRows, usePopover } from '@/react/hooks/usePopover'

// One menu of a Menubar: its trigger and Menu's panel of rows (MenuItem, MenuLabel, MenuSeparator) under it.
export interface MenubarMenuProps { label: string, width?: string, children?: ReactNode }

export function MenubarMenu({ label, width = '224px', children }: MenubarMenuProps) {
  const bar = useContext(MenubarContext)!
  const key = useId()
  const pop = usePopover({ side: 'bottom', align: 'start', gap: 4 })

  async function open(focus: 'first' | 'last' | 'none' = 'first', keyboard = true) {
    await pop.show({ keyboard })
    if (focus === 'none') return pop.panel.current?.focus({ preventScroll: true })
    const rows = [...(pop.panel.current?.querySelectorAll<HTMLElement>('[role^="menuitem"]:not([disabled])') ?? [])]
    ;(focus === 'last' ? rows.at(-1) : rows[0])?.focus()
  }
  const openRef = useRef(open)
  openRef.current = open
  useEffect(() => {
    const entry = { key, el: () => pop.anchor.current, open: () => openRef.current('first') }
    bar.entries.push(entry)
    bar.setFocused(f => f ?? key)
    return () => { bar.entries.splice(bar.entries.indexOf(entry), 1) }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (pop.open) bar.setActive(key)
    else bar.setActive(a => (a === key ? null : a))
  }, [pop.open]) // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => {
    if (bar.active !== key && pop.open) pop.hide(false, true)
  }, [bar.active]) // eslint-disable-line react-hooks/exhaustive-deps

  function onClick(event: MouseEvent) {
    if (pop.open) return pop.hide(event.detail === 0, event.detail === 0)
    void open(event.detail === 0 ? 'first' : 'none', event.detail === 0)
  }
  function onEnter() {
    if (bar.active && bar.active !== key) void open('none', true)
  }
  function onTriggerKey(event: KeyboardEvent) {
    if (event.key === 'ArrowRight' || event.key === 'ArrowLeft') {
      event.preventDefault()
      bar.move(key, event.key === 'ArrowRight' ? 1 : -1, false)
    }
    else if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      void open(event.key === 'ArrowDown' ? 'first' : 'last')
    }
  }
  function onPanelKey(event: KeyboardEvent) {
    if (event.key === 'ArrowRight' || event.key === 'ArrowLeft') {
      event.preventDefault()
      pop.hide(false, true)
      bar.move(key, event.key === 'ArrowRight' ? 1 : -1, true)
      return
    }
    onMenuRows(event, pop.panel.current, pop.hide)
  }
  return (
    <MenuClose.Provider value={() => pop.hide(true)}>
      <button
        data-ds="menubar-menu"
        ref={(el) => { pop.anchor.current = el }}
        type="button"
        role="menuitem"
        aria-haspopup="menu"
        aria-expanded={pop.open}
        tabIndex={bar.focused === key ? 0 : -1}
        className="inline-flex h-control-sm cursor-pointer items-center px-2.5 text-meta leading-5 font-medium text-fg transition-colors duration-120 ease-standard hover:bg-edge/45 aria-expanded:bg-surface focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-edge-focus max-md:h-control-touch max-md:text-ui"
        onClick={onClick}
        onPointerEnter={onEnter}
        onFocus={() => bar.setFocused(key)}
        onKeyDown={onTriggerKey}
      >
        {label}
      </button>
      <PopoverPanel data-ds="menubar-menu" pop={pop} role="menu" aria-label={label} tabIndex={-1} className="flex flex-col p-1" style={{ width }} onKeyDown={onPanelKey}>
        {children}
      </PopoverPanel>
    </MenuClose.Provider>
  )
}

export default MenubarMenu

import { html, type PropertyValues } from 'lit'
import { DsElement, define, tagName } from '@/elements/lib/element'
import styles from 'virtual:tw'

// Menubar.vue as <conare-menubar>: menu triggers in a row on the paper (shadcn's menubar in Conare's grammar): a
// hairline strip, 28px triggers in 12px medium, each opening a menu's square panel of rows (<conare-menubar-menu>).
// One trigger is in the tab order; Left and Right move along the row, Down, Enter or Space open, and with a menu open
// Left and Right open the next one. While one is open, pointing at another trigger switches to it at once.

/** What a <conare-menubar-menu> offers its bar. */
export interface MenubarEntry extends HTMLElement { focusTrigger(): void, openMenu(focus?: 'first' | 'last' | 'none'): Promise<void> }

/**
 * @summary Menu triggers in a row.
 * @slot - The menus: <conare-menubar-menu>.
 */
export class Menubar extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { label: {} }

	/** The bar's name for assistive tech. */
	label = ''
	/** The open menu, if any. */
	active: Element | null = null
	/** The trigger in the tab order (the first until another takes focus). */
	focused: Element | null = null

	/** The menus, in the order they sit. */
	entries() {
		return [...this.querySelectorAll<MenubarEntry>(tagName('menubar-menu'))]
	}
	/** The trigger in the tab order. */
	current() {
		return this.focused ?? this.entries()[0] ?? null
	}
	private refresh() {
		for (const m of this.entries()) (m as unknown as { requestUpdate(): void }).requestUpdate?.()
	}
	setActive(menu: Element | null) {
		if (this.active === menu) return
		this.active = menu
		this.refresh()
	}
	setFocused(menu: Element) {
		if (this.focused === menu) return
		this.focused = menu
		this.refresh()
	}
	move(from: Element, step: number, open: boolean) {
		const list = this.entries()
		const at = list.indexOf(from as MenubarEntry)
		const next = list[(at + step + list.length) % list.length]
		if (!next) return
		this.setFocused(next)
		next.focusTrigger()
		if (open) void next.openMenu('first')
	}

	protected firstUpdated(changed: PropertyValues<this>) {
		super.firstUpdated(changed)
		// Menus that drew before the bar was defined learn which trigger is in the tab order.
		this.refresh()
	}

	render() {
		return html`<div data-ds="menubar" role="menubar" aria-label=${this.label} class="inline-flex items-center gap-0.5 border border-edge bg-surface-subtle p-0.5"><slot></slot></div>`
	}
}

define('menubar', Menubar)

import { html, nothing, type PropertyValues } from 'lit'
import { DsElement, define, tagName } from '@/elements/lib/element'
import { CloseOnSelect, menuRows, onMenuRows } from '@/elements/lib/menu'
import { PopoverController, popoverStyles } from '@/elements/lib/popover'
import type { Menubar } from '@/elements/components/ui/menubar'
import styles from 'virtual:tw'

// MenubarMenu.vue as <conare-menubar-menu>: one menu of a <conare-menubar>: its trigger and a menu's panel of rows
// (<conare-menu-item>, <conare-menu-label>, <conare-menu-separator>) under it, in the top layer.

/**
 * @summary One menu of a menubar.
 * @slot - The rows.
 */
export class MenubarMenu extends DsElement {
	static styles = [DsElement.styles, popoverStyles, styles]
	static properties = { label: {}, width: {} }

	/** The trigger's text and the menu's name. */
	label = ''
	width = '224px'
	private wasOpen = false
	private pop = new PopoverController(this, {
		side: 'bottom',
		align: 'start',
		gap: 4,
		anchor: () => this.renderRoot.querySelector<HTMLElement>('button[role="menuitem"]'),
		panel: () => this.renderRoot.querySelector<HTMLElement>('.ds-pop'),
	})

	private get bar() {
		const b = this.closest(tagName('menubar')) as Menubar | null
		return b && typeof b.setActive === 'function' ? b : null
	}
	constructor() {
		super()
		// A chosen row closes the menu, focus back on the trigger.
		new CloseOnSelect(this, () => this.pop.hide(true))
	}

	private rows() {
		return menuRows(this)
	}
	/** Focuses the trigger (the bar's arrows). */
	focusTrigger() {
		this.renderRoot.querySelector<HTMLElement>('button[role="menuitem"]')?.focus()
	}
	/** Opens the menu, focusing its first or last row, or the panel. */
	async openMenu(focus: 'first' | 'last' | 'none' = 'first', keyboard = true) {
		await this.pop.show({ keyboard })
		await this.updateComplete
		if (focus === 'none') return this.renderRoot.querySelector<HTMLElement>('.ds-pop')?.focus({ preventScroll: true })
		const rows = this.rows()
		;(focus === 'last' ? rows.at(-1) : rows[0])?.focus()
	}

	private onClick = (event: MouseEvent) => {
		if (this.pop.open) return this.pop.hide(event.detail === 0, event.detail === 0)
		void this.openMenu(event.detail === 0 ? 'first' : 'none', event.detail === 0)
	}
	private onEnter = () => {
		const bar = this.bar
		if (bar?.active && bar.active !== this) void this.openMenu('none', true)
	}
	private onTriggerKey = (event: KeyboardEvent) => {
		if (event.key === 'ArrowRight' || event.key === 'ArrowLeft') {
			event.preventDefault()
			this.bar?.move(this, event.key === 'ArrowRight' ? 1 : -1, false)
		} else if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
			event.preventDefault()
			void this.openMenu(event.key === 'ArrowDown' ? 'first' : 'last')
		}
	}
	// Vue's onMenuRows, after Left and Right, which open the next menu.
	private onPanelKey = (event: KeyboardEvent) => {
		if (event.key === 'ArrowRight' || event.key === 'ArrowLeft') {
			event.preventDefault()
			this.pop.hide(false, true)
			this.bar?.move(this, event.key === 'ArrowRight' ? 1 : -1, true)
			return
		}
		onMenuRows(event, this.rows(), (refocus) => this.pop.hide(refocus))
	}
	protected updated(changed: PropertyValues<this>) {
		super.updated(changed)
		const bar = this.bar
		if (!bar) return
		if (this.pop.open !== this.wasOpen) {
			this.wasOpen = this.pop.open
			if (this.pop.open) bar.setActive(this)
			else if (bar.active === this) bar.setActive(null)
		}
		if (bar.active !== this && this.pop.open) this.pop.hide(false, true)
	}

	render() {
		const bar = this.bar
		const tabbable = !bar || bar.current() === this
		const panel = this.pop.rendered
			? html`<div data-ds="menubar-menu" popover="manual" class="ds-pop flex flex-col p-1" role="menu" aria-label=${this.label} tabindex="-1" data-side=${this.pop.pos.side} ?data-instant=${this.pop.instant} ?data-placed=${this.pop.pos.placed} style=${this.pop.style(`width: ${this.width}`)} @keydown=${this.onPanelKey} @focusout=${this.pop.onFocusOut}><slot></slot></div>`
			: nothing
		return html`<button data-ds="menubar-menu" type="button" role="menuitem" aria-haspopup="menu" aria-expanded=${String(this.pop.open)} tabindex=${tabbable ? 0 : -1} class="inline-flex h-control-sm cursor-pointer items-center px-2.5 text-meta leading-5 font-medium text-fg transition-colors duration-120 ease-standard hover:bg-edge/45 aria-expanded:bg-surface focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-edge-focus max-md:h-control-touch max-md:text-ui" @click=${this.onClick} @pointerenter=${this.onEnter} @focus=${() => this.bar?.setFocused(this)} @keydown=${this.onTriggerKey}>${this.label}</button>${panel}`
	}
}

define('menubar-menu', MenubarMenu)
